 [Fact]public async Task Media_memories_read_and_index_require_coach_current_assignment()
 {
  using var coach=await Mobile(AcademyRole.Coach);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var opts=await coach.GetFromJsonAsync<JsonElement>("/api/v1/evaluations/options");var id=opts.GetProperty("enrollments")[0].GetProperty("id").GetGuid();var e=await db.SportEnrollments.AsNoTracking().SingleAsync(e=>e.Id==id);var hash=Academy.Api.Mobile.MobileAuthenticationHandler.Hash(coach.DefaultRequestHeaders.Authorization!.Parameter!);var member=await db.MobileSessions.Where(s=>s.AccessTokenHash==hash).Select(s=>s.MembershipId).SingleAsync();var a=await db.StaffGroupAssignments.SingleAsync(a=>a.AcademyMembershipId==member&&a.TrainingGroupId==e.TrainingGroupId&&a.IsActive);var url=$"/api/v1/assets/memories?groupId={e.TrainingGroupId}";
  try{(await coach.GetAsync(url)).EnsureSuccessStatusCode();a.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await coach.GetAsync(url+"&format=csv")).StatusCode);}finally{a.IsActive=true;await db.SaveChangesAsync();}
 }
 [Fact]public async Task Media_memories_delegated_read_keeps_branch_scope_and_existing_narrow_sport_fail_closed_policy()=>await DelegateFixture(async(owner,admin,db,group,member)=>{
  var membership=await db.AcademyMemberships.SingleAsync(m=>m.Id==member);membership.AllSports=true;
  var grant=await db.StaffActionGrants.SingleOrDefaultAsync(g=>g.MembershipId==member&&g.Module=="media");var old=grant==null?null:JsonSerializer.Serialize(grant);grant??=new(){Id=Guid.NewGuid(),AcademyId=group.AcademyId,MembershipId=member,Module="media"};if(old==null)db.StaffActionGrants.Add(grant);
  try{grant.Read=true;grant.Add=false;grant.Edit=false;grant.Delete=false;grant.IsActive=true;await db.SaveChangesAsync();var url=$"/api/v1/assets/memories?groupId={group.Id}";(await admin.GetAsync(url+"&format=text")).EnsureSuccessStatusCode();var branch=await db.MembershipBranchAccesses.SingleAsync(a=>a.MembershipId==member&&a.BranchId==group.BranchId);branch.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await admin.GetAsync(url)).StatusCode);branch.IsActive=true;membership.AllSports=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await admin.GetAsync(url+"&format=csv")).StatusCode);membership.AllSports=true;grant.Read=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await admin.GetAsync(url)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await admin.GetAsync(url+"&format=csv")).StatusCode);}
  finally{if(old==null)db.StaffActionGrants.Remove(grant);else db.Entry(grant).CurrentValues.SetValues(JsonSerializer.Deserialize<StaffActionGrant>(old)!);await db.SaveChangesAsync();}
 });
 private static async Task<Guid> MemoryPlayerUpload(HttpClient owner,Guid player,DateOnly date,string caption)
 {
  var csrf=await owner.GetFromJsonAsync<JsonElement>("/api/v1/auth/csrf");using var f=new MultipartFormDataContent();var file=new ByteArrayContent(MediaPng);file.Headers.ContentType=new MediaTypeHeaderValue("image/png");f.Add(file,"file","synthetic-memory.png");foreach(var(k,v)in new Dictionary<string,string>{{"purpose","Media"},{"playerId",player.ToString()},{"eventOn",date.ToString("yyyy-MM-dd")},{"caption",caption},{"privacyConfirmed","true"}})f.Add(new StringContent(v),k);using var req=new HttpRequestMessage(HttpMethod.Post,"/api/v1/assets/upload"){Content=f};req.Headers.Add("X-CSRF-TOKEN",csrf.GetProperty("token").GetString());return await MediaCreated(await owner.SendAsync(req));
 }
 [Fact]public async Task Media_memories_reuse_the_live_audience_and_never_restore_old_consent_or_export_private_links()
 {
  using var owner=await Staff();using var foreign=await Staff(DemoSeed.FutureOwnerEmail);var f=await LifecycleFamily(owner);using var family=f.Family;var root=$"/api/v1/assets/memories?playerId={f.Player}";var money=await owner.GetStringAsync("/api/v1/reports/financial?from=2026-09-01&to=2026-09-28");var id=await MediaCreated(await PrivacyUpload(owner,f.Group,f.Day,f.Player));var previous=f.Day.AddMonths(-1);var prior=await MemoryPlayerUpload(owner,f.Player,previous," =SUM(A1)");
  var current=await family.GetFromJsonAsync<JsonElement>(root);Assert.Equal(f.Day.ToString("yyyy-MM"),current.GetProperty("month").GetString());Assert.Equal(1,current.GetProperty("total").GetInt32());Assert.Equal(id,current.GetProperty("items")[0].GetProperty("id").GetGuid());Assert.Equal(1,current.GetProperty("images").GetInt32());
  var past=root+$"&month={previous:yyyy-MM}";var old=await family.GetFromJsonAsync<JsonElement>(past);Assert.Equal(prior,old.GetProperty("items")[0].GetProperty("id").GetGuid());Assert.Equal(0,(await family.GetFromJsonAsync<JsonElement>(past+$"&groupId={f.Group}")).GetProperty("total").GetInt32());var csv=await family.GetAsync(past+"&format=csv");csv.EnsureSuccessStatusCode();var text=await csv.Content.ReadAsStringAsync();Assert.Contains("'=SUM(A1)",text);Assert.DoesNotContain("/api/",text);Assert.DoesNotContain("access=",text);Assert.DoesNotContain("StorageName",text);Assert.Equal(text,(await family.GetFromJsonAsync<JsonElement>(past+"&format=text")).GetProperty("text").GetString());Assert.Contains("no-store",csv.Headers.CacheControl!.ToString());
  Assert.Equal(HttpStatusCode.NotFound,(await foreign.GetAsync(root)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await family.GetAsync(root.Replace(f.Player.ToString(),Guid.NewGuid().ToString()))).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await family.GetAsync(root+$"&month={f.Day.AddMonths(1):yyyy-MM}")).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await owner.GetAsync("/api/v1/assets/memories")).StatusCode);
  var consent=$"/api/v1/guardian/children/{f.Player}/group-media-consent";(await Send(family,consent,new GroupMediaConsentWrite(false,1,Guid.NewGuid()))).EnsureSuccessStatusCode();Assert.Equal(0,(await family.GetFromJsonAsync<JsonElement>(root)).GetProperty("total").GetInt32());Assert.DoesNotContain(id.ToString(),await owner.GetStringAsync($"/api/v1/assets/memories?groupId={f.Group}"));(await Send(family,consent,new GroupMediaConsentWrite(true,2,Guid.NewGuid()))).EnsureSuccessStatusCode();Assert.Equal(0,(await family.GetFromJsonAsync<JsonElement>(root)).GetProperty("total").GetInt32());
  var fresh=await MediaCreated(await PrivacyUpload(owner,f.Group,f.Day,f.Player));Assert.Equal(fresh,(await family.GetFromJsonAsync<JsonElement>(root)).GetProperty("items")[0].GetProperty("id").GetGuid());(await Send(owner,$"/api/v1/assets/{fresh}/withdraw",new MediaWithdrawalWrite(Guid.NewGuid(),null))).EnsureSuccessStatusCode();Assert.DoesNotContain(fresh.ToString(),await family.GetStringAsync(root+"&format=csv"));Assert.Equal(HttpStatusCode.NotFound,(await family.GetPrivateAssetAsync(factory,$"/api/v1/assets/{fresh}")).StatusCode);Assert.Equal(money,await owner.GetStringAsync("/api/v1/reports/financial?from=2026-09-01&to=2026-09-28"));
  await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();Assert.False(await db.SubscriptionPeriods.AnyAsync(p=>db.SportEnrollments.Any(e=>e.Id==p.SportEnrollmentId&&e.PlayerId==f.Player)));var link=await db.GuardianPlayerLinks.SingleAsync(l=>l.PlayerId==f.Player);link.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await family.GetAsync(past+"&format=text")).StatusCode);
 }
 [Fact]public async Task Media_memories_pages_and_metadata_index_include_only_available_reviewed_sources_even_for_owner()
 {
  using var owner=await Staff();var f=await LifecycleFamily(owner);using var family=f.Family;var ids=new List<Guid>();for(var i=0;i<26;i++)ids.Add(await MemoryPlayerUpload(owner,f.Player,f.Day,"ذكرى تدريب اصطناعية "+i));var root=$"/api/v1/assets/memories?playerId={f.Player}";var a=await family.GetFromJsonAsync<JsonElement>(root);Assert.Equal(26,a.GetProperty("total").GetInt32());Assert.Equal(25,a.GetProperty("items").GetArrayLength());Assert.True(a.GetProperty("hasMore").GetBoolean());Assert.Single((await family.GetFromJsonAsync<JsonElement>(root+"&page=1")).GetProperty("items").EnumerateArray());var index=await family.GetStringAsync(root+"&format=csv");Assert.All(ids,id=>Assert.Contains(id.ToString(),index));
  (await Send(owner,$"/api/v1/assets/{ids[0]}/delete",new MediaErasureWrite(Guid.NewGuid(),null))).EnsureSuccessStatusCode();Assert.Equal(25,(await family.GetFromJsonAsync<JsonElement>(root)).GetProperty("total").GetInt32());Assert.DoesNotContain(ids[0].ToString(),await owner.GetStringAsync(root));
  // A specifically owned synthetic legacy/expired row, without touching or backfilling real originals.
  await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var source=await db.PrivateAssets.AsNoTracking().SingleAsync(a=>a.Id==ids[1]);source.Id=Guid.NewGuid();source.StorageName=Guid.NewGuid().ToString("N");source.MediaPolicyVersion=0;source.RetainUntilUtc=null;source.DeleteOnExpiry=false;db.PrivateAssets.Add(source);await db.SaveChangesAsync();var expired=await db.PrivateAssets.AsNoTracking().SingleAsync(a=>a.Id==ids[1]);expired.Id=Guid.NewGuid();expired.StorageName=Guid.NewGuid().ToString("N");expired.CreatedAtUtc=DateTimeOffset.UtcNow.AddDays(-3);expired.UpdatedAtUtc=expired.CreatedAtUtc;expired.RetainUntilUtc=DateTimeOffset.UtcNow.AddDays(-1);expired.DeleteOnExpiry=false;db.PrivateAssets.Add(expired);await db.SaveChangesAsync();Assert.Equal(25,(await owner.GetFromJsonAsync<JsonElement>(root)).GetProperty("total").GetInt32());var final=await owner.GetStringAsync(root+"&format=csv");Assert.DoesNotContain(source.Id.ToString(),final);Assert.DoesNotContain(expired.Id.ToString(),final);
 }
}
